import {Ajv} from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validator = new Ajv({strict: false, validateFormats: false, ownProperties: true});
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validate: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validate = this.validator.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid input schema for tool ${resolved.name}: ${String(error)}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  private dynamicValidator(schema: ToolDefinition['inputSchema']): ValidateFunction {
    const cached = this.dynamicValidators.get(schema);
    if (cached) return cached;
    const validate = this.validator.compile(schema);
    this.dynamicValidators.set(schema, validate);
    return validate;
  }

  /** Validates input before execution; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = tool.validate ?? this.dynamicValidator(this.resolveDefinition(tool.definitionSource).inputSchema);
    if (!validate(input)) {
      const errors = validate.errors ?? [];
      const details = errors
        .map(error => {
          const property =
            error.keyword === 'required'
              ? String(error.params.missingProperty)
              : error.keyword === 'additionalProperties'
                ? String(error.params.additionalProperty)
                : '';
          const path = property
            ? `${error.instancePath}/${property.replace(/~/g, '~0').replace(/\//g, '~1')}`
            : error.instancePath;
          return `${path || '(root)'} ${error.keyword}: ${error.message ?? 'validation failed'}`;
        })
        .join('; ');
      log.warn('tool', 'input validation failed', {name, details});
      return {result: `Invalid input: ${details}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#10
it('caches dynamic validators by schema reference', async () => {
  const registry = new ToolRegistry();
  const schemas = [
    {type: 'object', required: ['location']},
    {type: 'object', required: ['unit']},
  ];
  let current = 0;
  registry.register(
    () => ({name: 'weather', description: 'Weather', inputSchema: schemas[current]}),
    async () => 'ok'
  );

  const compile = jest.spyOn(registry['validator'], 'compile');
  const first = await registry.execute('weather', {});
  const firstCompileCount = compile.mock.calls.length;
  await registry.execute('weather', {location: 'Paris'});
  current = 1;
  const second = await registry.execute('weather', {});
  await registry.execute('weather', {unit: 'C'});
  current = 0;
  await registry.execute('weather', {location: 'Paris'});
  expect({
    firstCompileCount,
    first: first.result.includes('location'),
    second: second.result.includes('unit'),
    finalCompileCount: compile.mock.calls.length,
  }).toEqual({firstCompileCount: 1, first: true, second: true, finalCompileCount: 2});
});
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#13
it('rejects an inherited required property', async () => {
  const registry = new ToolRegistry();
  const executor = jest.fn(async () => 'sunny');
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object', required: ['location']}},
    executor
  );
  const input = Object.create({location: 'Paris'}) as Record<string, unknown>;
  const response = await registry.execute('weather', input);
  expect({
    required: /location.*required|required.*location/i.test(response.result),
    calls: executor.mock.calls.length,
  }).toEqual({required: true, calls: 0});
});
